#####################################################################################
# Project: Coffee Rhizosphere Microbiome - 16S rRNA Metabarcoding
# Script: 06_taxonomic_composition.R
# Author: Gustavo Goncalves
# Last edit: 18/11/2026
#
# Description:
# Analysis of taxonomic composition and relative abundance of taxa in coffee
# rhizosphere microbiome samples. Generates taxonomic summaries and phylum-level
# composition plots, including the 10 most abundant phyla and an "Other" category.
#
# Notes:
#   This script requires the phyloseq object generated by 03_phyloseq_object.R.
#####################################################################################

# Load project configuration
source("projects/coffee/config.R")

# Set up packages
library(phyloseq); packageVersion("phyloseq")
library(ggplot2); packageVersion("ggplot2")

theme_set(theme_bw())

# Create taxonomic composition directory
tax_path <- file.path(results_path, "taxonomic_composition")
dir.create(tax_path, recursive = TRUE, showWarnings = FALSE)

# Load phyloseq object
ps <- readRDS(file.path(objects_path, "phyloseq_object.rds"))


#####################################################################################
# Taxonomic summary
#####################################################################################

# Extract taxonomy table
taxa <- as.data.frame(tax_table(ps))

# ASVs assigned at each taxonomic level
assigned <- colSums(
  !is.na(taxa) & taxa != ""
)

assigned_percent <- round(
  100 * assigned / nrow(taxa),
  2
)

# Taxa with highest number of assigned ASVs
top_phylum <- head(
  sort(table(taxa$Phylum), decreasing = TRUE),
  15
)

top_class <- head(
  sort(table(taxa$Class), decreasing = TRUE),
  15
)

top_genus <- head(
  sort(table(taxa$Genus), decreasing = TRUE),
  20
)

# Display results
print(assigned)
print(assigned_percent)
print(top_phylum)
print(top_class)
print(top_genus)

# Save taxonomic summary
sink(file.path(tax_path, "taxonomic_summary.txt"))

cat("Total ASVs:", nrow(taxa), "\n\n")

cat("ASVs assigned at each taxonomic level\n")
print(assigned)

cat("\nPercentage of assigned ASVs\n")
print(assigned_percent)

cat("\nTop 15 phyla by number of ASVs\n")
print(top_phylum)

cat("\nTop 15 classes by number of ASVs\n")
print(top_class)

cat("\nTop 20 genera by number of ASVs\n")
print(top_genus)

sink()


#####################################################################################
# Relative abundance
#####################################################################################

# Transform counts to relative abundance
ps.rel <- transform_sample_counts(
  ps,
  function(x) x / sum(x)
)

# Replace missing phylum assignments
tax_table(ps.rel)[, "Phylum"][
  is.na(tax_table(ps.rel)[, "Phylum"]) |
    tax_table(ps.rel)[, "Phylum"] == ""
] <- "Unassigned"

# Agglomerate ASVs at Phylum level
ps.phylum <- tax_glom(
  ps.rel,
  taxrank = "Phylum",
  NArm = FALSE
)

# Convert to data frame
phylum.df <- psmelt(ps.phylum)

# Calculate total relative abundance by phylum
phylum.total <- aggregate(
  Abundance ~ Phylum,
  data = phylum.df,
  FUN = sum
)

phylum.total <- phylum.total[
  order(phylum.total$Abundance, decreasing = TRUE),
]

# Select the 10 most abundant phyla
top10 <- head(phylum.total$Phylum, 10)

# Group remaining phyla as Other
phylum.df$Phylum <- as.character(phylum.df$Phylum)

phylum.df$Phylum[
  !phylum.df$Phylum %in% top10
] <- "Other"

# Sum relative abundances by sample and phylum
phylum.sample <- aggregate(
  Abundance ~ Sample + Phylum,
  data = phylum.df,
  FUN = sum
)

# Add sample metadata
metadata <- data.frame(sample_data(ps))
metadata$Sample <- rownames(metadata)

phylum.sample <- merge(
  phylum.sample,
  metadata,
  by = "Sample",
  sort = FALSE
)

# Set phylum order
phylum.order <- c(top10, "Other")

phylum.sample$Phylum <- factor(
  phylum.sample$Phylum,
  levels = phylum.order
)

# Set color palette
phylum.colors <- c(
  setNames(
    grDevices::hcl.colors(length(top10), "Dark 3"),
    top10
  ),
  Other = "grey85"
)

# Save relative abundance table
write.csv(
  phylum.sample,
  file.path(tax_path, "phylum_relative_abundance.csv"),
  row.names = FALSE
)


#####################################################################################
# Phylum-level composition
#####################################################################################

# Relative abundance by SampleID
p1 <- ggplot(
  phylum.sample,
  aes(
    x = SampleID,
    y = Abundance,
    fill = Phylum
  )
) +
  geom_col(
    color = "grey50",
    linewidth = 0.2
  ) +
  scale_fill_manual(
    values = phylum.colors,
    drop = FALSE
  ) +
  scale_y_continuous(
    labels = function(x) paste0(x * 100, "%")
  ) +
  labs(
    x = "Sample",
    y = "Relative abundance",
    fill = "Phylum"
  ) +
  theme(
    axis.text.x = element_text(
      angle = 90,
      hjust = 1,
      vjust = 0.5
    )
  )

print(p1)

ggsave(
  filename = file.path(tax_path, "phylum_by_sample.png"),
  plot = p1,
  width = 16,
  height = 7,
  dpi = 300
)


# Relative abundance by SampleID, faceted by Farm
p2 <- ggplot(
  phylum.sample,
  aes(
    x = SampleID,
    y = Abundance,
    fill = Phylum
  )
) +
  geom_col(
    color = "grey50",
    linewidth = 0.2
  ) +
  facet_wrap(
    ~Farm,
    scales = "free_x"
  ) +
  scale_fill_manual(
    values = phylum.colors,
    drop = FALSE
  ) +
  scale_y_continuous(
    labels = function(x) paste0(x * 100, "%")
  ) +
  labs(
    x = "Sample",
    y = "Relative abundance",
    fill = "Phylum"
  ) +
  theme(
    axis.text.x = element_text(
      angle = 90,
      hjust = 1,
      vjust = 0.5
    )
  )

print(p2)

ggsave(
  filename = file.path(tax_path, "phylum_by_sample_farm.png"),
  plot = p2,
  width = 16,
  height = 9,
  dpi = 300
)


#####################################################################################
# Mean relative abundance by CropStage and Farm
#####################################################################################

# Calculate mean relative abundance per group
phylum.mean <- aggregate(
  Abundance ~ Farm + CropStage + Phylum,
  data = phylum.sample,
  FUN = mean
)

# Save mean relative abundance table
write.csv(
  phylum.mean,
  file.path(tax_path, "phylum_mean_relative_abundance.csv"),
  row.names = FALSE
)

# Relative abundance by CropStage, faceted by Farm
p3 <- ggplot(
  phylum.mean,
  aes(
    x = CropStage,
    y = Abundance,
    fill = Phylum
  )
) +
  geom_col(
    color = "grey50",
    linewidth = 0.2
  ) +
  facet_wrap(~Farm) +
  scale_fill_manual(
    values = phylum.colors,
    drop = FALSE
  ) +
  scale_y_continuous(
    labels = function(x) paste0(x * 100, "%")
  ) +
  labs(
    x = "Crop stage",
    y = "Mean relative abundance",
    fill = "Phylum"
  ) +
  theme(
    axis.text.x = element_text(
      angle = 45,
      hjust = 1
    )
  )

print(p3)

ggsave(
  filename = file.path(tax_path, "phylum_by_cropstage_farm.png"),
  plot = p3,
  width = 14,
  height = 8,
  dpi = 300
)


#####################################################################################
# Family-level composition
#####################################################################################

# Replace missing family assignments
tax_table(ps.rel)[, "Family"][
  is.na(tax_table(ps.rel)[, "Family"]) |
    tax_table(ps.rel)[, "Family"] == ""
] <- "Unassigned"

# Agglomerate ASVs at Family level
ps.family <- tax_glom(
  ps.rel,
  taxrank = "Family",
  NArm = FALSE
)

# Convert to data frame
family.df <- psmelt(ps.family)

# Calculate total relative abundance by family
family.total <- aggregate(
  Abundance ~ Family,
  data = family.df,
  FUN = sum
)

family.total <- family.total[
  order(family.total$Abundance, decreasing = TRUE),
]

# Select the 10 most abundant families
top10.family <- head(family.total$Family, 10)

# Group remaining families as Other
family.df$Family <- as.character(family.df$Family)

family.df$Family[
  !family.df$Family %in% top10.family
] <- "Other"

# Sum relative abundances by sample and family
family.sample <- aggregate(
  Abundance ~ Sample + Family,
  data = family.df,
  FUN = sum
)

# Include absent families with zero abundance
family.grid <- expand.grid(
  Sample = sample_names(ps),
  Family = unique(c(top10.family, "Other")),
  stringsAsFactors = FALSE
)

family.sample <- merge(
  family.grid,
  family.sample,
  by = c("Sample", "Family"),
  all.x = TRUE,
  sort = FALSE
)

family.sample$Abundance[
  is.na(family.sample$Abundance)
] <- 0

# Add sample metadata
family.sample <- merge(
  family.sample,
  metadata,
  by = "Sample",
  sort = FALSE
)

# Set family order
family.order <- unique(c(top10.family, "Other"))

family.sample$Family <- factor(
  family.sample$Family,
  levels = family.order
)

# Set color palette
family.colors <- c(
  setNames(
    grDevices::hcl.colors(length(top10.family), "Dark 3"),
    top10.family
  ),
  Other = "grey85"
)

# Save relative abundance table
write.csv(
  family.sample,
  file.path(tax_path, "family_relative_abundance.csv"),
  row.names = FALSE
)


#####################################################################################
# Family-level composition plots
#####################################################################################

# Relative abundance by SampleID
p4 <- ggplot(
  family.sample,
  aes(
    x = SampleID,
    y = Abundance,
    fill = Family
  )
) +
  geom_col(
    color = "grey70",
    linewidth = 0.15
  ) +
  scale_fill_manual(
    values = family.colors,
    drop = FALSE
  ) +
  scale_y_continuous(
    labels = function(x) paste0(x * 100, "%")
  ) +
  labs(
    x = "Sample",
    y = "Relative abundance",
    fill = "Family"
  ) +
  theme(
    axis.text.x = element_text(
      angle = 90,
      hjust = 1,
      vjust = 0.5
    )
  )

print(p4)

ggsave(
  filename = file.path(tax_path, "family_by_sample.png"),
  plot = p4,
  width = 16,
  height = 7,
  dpi = 300
)


